import {el,link,json,normalize,rich,status,flagsReady} from './core.js';
const host=document.getElementById('ml-effects-page');
if(host){if(!(await flagsReady).effectsGlossary)status(host,'The effects glossary is currently disabled.');else try{
 const effects=await json('/images/mlg-assets/data-effects.json');const controls=el('div',{class:'ml-search-controls'}),input=el('input',{type:'search',id:'effect-search',placeholder:'Search names or descriptions…'}),filter=el('select',{id:'effect-type'});for(const type of ['All effects',...new Set(Object.values(effects).map(e=>e.type).filter(Boolean))])filter.append(el('option',{},type));const a=el('div'),b=el('div');a.append(el('label',{for:input.id},'Find an effect'),input);b.append(el('label',{for:filter.id},'Type'),filter);controls.append(a,b);const message=el('p',{role:'status',class:'ml-muted'}),grid=el('div',{class:'ml-effect-grid'});host.replaceChildren(controls,message,grid);
 const descriptions=e=>Object.entries(e).filter(([k,v])=>/^description\d*$/.test(k)&&typeof v==='string').sort(([a],[b])=>a.localeCompare(b,undefined,{numeric:true}));
 function render(){grid.replaceChildren();const query=normalize(input.value);let count=0;for(const [id,e]of Object.entries(effects).sort(([,a],[,b])=>a.name.localeCompare(b.name))){const text=descriptions(e).map(([,v])=>v).join(' ');if(filter.value!=='All effects'&&e.type!==filter.value||!normalize(e.name+' '+id+' '+text).includes(query))continue;count++;const card=el('article',{class:'ml-effect-card',id}),title=el('h2');if(e.icon){const icon=el('img',{src:e.icon,alt:'',loading:'lazy',width:'25',height:'25'});icon.onerror=()=>icon.remove();title.append(icon);}title.append(link(e.name,'#'+id));card.append(title,el('p',{class:'ml-muted'},e.type||'Mechanic'));for(const [,desc]of descriptions(e)){const p=el('p');const parts=desc.split(/(\{\{effect:[^}]+\}\})/g);for(const part of parts){const match=part.match(/^\{\{effect:([^}]+)\}\}$/);if(match){const target=effects[match[1]];p.append(link(target?.name||match[1],'#'+match[1]));}else p.append(rich(part));}card.append(p);}card.append(link('Open effect details','/ml-game/apps/effect.html?effect='+encodeURIComponent(id)));grid.append(card);}message.textContent=count+' '+(count===1?'effect':'effects')+(count?'':' — try a different search');}
 function revealHash(){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{return;}if(!id||!effects[id])return;input.value='';filter.selectedIndex=0;render();document.getElementById(id)?.scrollIntoView({block:'start'});}
 input.addEventListener('input',render);filter.addEventListener('change',render);window.addEventListener('hashchange',revealHash);render();if(location.hash)requestAnimationFrame(revealHash);
 }catch{status(host,'Effects could not load. Refresh to try again.');}}
